t.script:
(function () {
    const steps = Array.from(document.querySelectorAll(".js-list-step"));
    const indicator = document.getElementById("iem_list_form_step_indicator");
    const prevBtn = document.getElementById("iem_list_prev_step");
    const nextBtn = document.getElementById("iem_list_next_step");
    const submitBtn = document.getElementById("iem_list_submit_form");
    const validateAccessBtn = document.getElementById("iem_list_validate_access");
    const clientMessage = document.getElementById("iem_list_form_client_message");
    const publicSuccessMessage = document.querySelector(".js-public-success-message");
    const csrfTokenInput = document.querySelector('input[name="csrf_token"]');
    const accessPasswordInput = document.querySelector('input[name="access_password"]');
    const toggleAccessPasswordBtn = document.getElementById("iem_list_toggle_access_password");
    const listSelect = document.getElementById("iem_list_select");
    const listInfoBox = document.getElementById("iem_list_info_box");
    const memberIdInput = document.getElementById("iem_list_member_id");
    const memberQueryInput = document.getElementById("iem_list_member_query");
    const memberSelected = document.getElementById("iem_list_member_selected");
    const memberResults = document.getElementById("iem_list_member_results");
    const memberHelp = document.getElementById("iem_list_member_help");
    const booleanRow = document.getElementById("iem_list_boolean_row");
    const amountRow = document.getElementById("iem_list_amount_row");
    const textRow = document.getElementById("iem_list_text_row");
    const imageRow = document.getElementById("iem_list_image_row");
    const booleanLabel = document.getElementById("iem_list_boolean_label");
    const amountLabel = document.getElementById("iem_list_amount_label");
    const textLabel = document.getElementById("iem_list_text_label");
    const imageLabel = document.getElementById("iem_list_image_label");
    const currencySymbol = document.getElementById("iem_list_currency_symbol");
    const detailsRow = document.getElementById("iem_list_details_row");
    const booleanInput = document.getElementById("iem_list_extra_boolean");
    const amountInput = document.getElementById("iem_list_extra_amount");
    const textInput = document.getElementById("iem_list_extra_text");
    const imageInput = document.getElementById("iem_list_extra_image");
    const imagePreview = document.getElementById("iem_list_image_preview");
    const detailsPreview = document.getElementById("iem_list_details_preview");
    const accessValidated = ;
    if (!steps.length || !indicator || !prevBtn || !nextBtn || !submitBtn || !listSelect || !memberQueryInput || !memberIdInput || !memberResults) {
        return;
    }

    let currentStep = 0;
    let searchTimer = null;

    function showClientMessage(type, text) {
        if (!clientMessage) {
            return;
        }
        if (!text) {
            clientMessage.classList.add("d-none");
            clientMessage.textContent = "";
            clientMessage.classList.remove("alert-success", "alert-danger", "alert-warning", "alert-info");
            return;
        }
        clientMessage.classList.remove("d-none", "alert-success", "alert-danger", "alert-warning", "alert-info");
        clientMessage.classList.add(type === "success" ? "alert-success" : "alert-danger");
        clientMessage.textContent = text;
    }

    async function postAndReadJson(url, params) {
        const body = new URLSearchParams();
        Object.keys(params || {}).forEach((key) => {
            body.append(key, params[key] || "");
        });
        if (csrfTokenInput) {
            body.append("csrf_token", csrfTokenInput.value || "");
        }
        const response = await fetch(url, {
            method: "POST",
            headers: {
                "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
                "X-Requested-With": "XMLHttpRequest",
            },
            body: body.toString(),
            credentials: "same-origin",
        });
        return response.json();
    }

    function selectedListOption() {
        return listSelect.selectedOptions.length ? listSelect.selectedOptions[0] : null;
    }

    function hasExtraStep() {
        const option = selectedListOption();
        return option && option.value && option.dataset.hasExtraStep === "1";
    }

    function hasDetails() {
        const option = selectedListOption();
        return option && option.value && option.dataset.hasDetails === "1";
    }

    function hasFinalStep() {
        return hasExtraStep() || hasDetails();
    }

    function totalSteps() {
        return hasFinalStep() ? 3 : 2;
    }

    function setStep(step) {
        currentStep = step;
        steps.forEach((el) => {
            el.classList.toggle("d-none", Number(el.dataset.step) !== currentStep);
        });
        indicator.textContent = `Paso ${currentStep + 1} de ${totalSteps()}`;
        prevBtn.classList.toggle("d-none", currentStep === 0);
        nextBtn.classList.toggle("d-none", currentStep === 0 || currentStep >= totalSteps() - 1);
        submitBtn.classList.toggle("d-none", currentStep !== totalSteps() - 1);
        if (validateAccessBtn) {
            validateAccessBtn.classList.toggle("d-none", currentStep !== 0);
        }
        updateStepRequiredFields();
    }

    function updateRequiredState(element, enabled) {
        if (!element) {
            return;
        }
        element.required = !!enabled;
    }

    function updateStepRequiredFields() {
        updateRequiredState(accessPasswordInput, currentStep === 0);
        updateRequiredState(listSelect, currentStep === 1);
        updateRequiredState(booleanInput, currentStep === 2 && !booleanRow.classList.contains("d-none"));
        updateRequiredState(amountInput, currentStep === 2 && !amountRow.classList.contains("d-none"));
        updateRequiredState(textInput, currentStep === 2 && !textRow.classList.contains("d-none"));
        updateRequiredState(imageInput, currentStep === 2 && !imageRow.classList.contains("d-none"));
    }

    function applyListConfiguration() {
        const option = selectedListOption();
        const listId = option && option.value ? option.value : "";
        const infoTemplate = listId ? document.querySelector(`.js-list-info-template[data-list-id="${listId}"]`) : null;
        listInfoBox.innerHTML = infoTemplate ? infoTemplate.innerHTML : "Selecciona una lista para ver su información.";

        const showBoolean = !!(option && option.dataset.showBoolean === "1");
        const showAmount = !!(option && option.dataset.showAmount === "1");
        const showText = !!(option && option.dataset.showText === "1");
        const showImage = !!(option && option.dataset.showImage === "1");
        const showDetails = !!(option && option.dataset.hasDetails === "1");

        booleanRow.classList.toggle("d-none", !showBoolean);
        amountRow.classList.toggle("d-none", !showAmount);
        textRow.classList.toggle("d-none", !showText);
        imageRow.classList.toggle("d-none", !showImage);
        detailsRow.classList.toggle("d-none", !showDetails);

        booleanLabel.textContent = option && option.dataset.booleanLabel ? option.dataset.booleanLabel : "Si/No";
        amountLabel.textContent = option && option.dataset.amountLabel ? option.dataset.amountLabel : "Monto";
        textLabel.textContent = option && option.dataset.textLabel ? option.dataset.textLabel : "Notas";
        imageLabel.textContent = option && option.dataset.imageLabel ? option.dataset.imageLabel : "Imagen";
        if (currencySymbol) {
            currencySymbol.textContent = option && option.dataset.currencySymbol ? option.dataset.currencySymbol : "";
        }
        if (detailsPreview) {
            detailsPreview.value = option && option.dataset.details ? option.dataset.details : "";
        }

        updateStepRequiredFields();

        if (currentStep >= totalSteps()) {
            setStep(totalSteps() - 1);
        } else {
            setStep(currentStep);
        }
    }

    function hideMemberResults() {
        memberResults.classList.add("d-none");
        memberResults.innerHTML = "";
    }

    function setSelectedMember(memberId, memberName, alreadyAdded) {
        memberIdInput.value = memberId || "";
        memberQueryInput.value = memberName || "";
        if (memberSelected) {
            memberSelected.textContent = memberName ? `Seleccionado: ${memberName}` : "";
        }
        if (alreadyAdded === "1") {
            showClientMessage("error", "El miembro ya fue agregado a esta lista.");
            return;
        }
        showClientMessage("", "");
    }

    function renderMemberResults(members) {
        memberResults.innerHTML = "";
        if (!(members || []).length) {
            const empty = document.createElement("div");
            empty.className = "list-group-item text-muted";
            empty.textContent = "No se encontraron miembros.";
            memberResults.appendChild(empty);
            memberResults.classList.remove("d-none");
            return;
        }
        (members || []).forEach((member) => {
            const button = document.createElement("button");
            button.type = "button";
            button.className = `list-group-item list-group-item-action${member.already_added ? " text-muted" : ""}`;
            button.textContent = member.already_added ? `${member.name} (Ya agregado)` : member.name;
            button.dataset.memberId = String(member.id);
            button.dataset.memberName = member.name;
            button.dataset.alreadyAdded = member.already_added ? "1" : "0";
            button.addEventListener("click", function () {
                setSelectedMember(
                    button.dataset.memberId || "",
                    button.dataset.memberName || "",
                    button.dataset.alreadyAdded || "0"
                );
                hideMemberResults();
            });
            memberResults.appendChild(button);
        });
        memberResults.classList.remove("d-none");
    }

    async function searchMembers() {
        const listId = listSelect.value;
        if (!listId) {
            hideMemberResults();
            return;
        }
        const query = memberQueryInput ? (memberQueryInput.value || "").trim() : "";
        if (query.length < 3) {
            hideMemberResults();
            return;
        }
        try {
            const payload = await postAndReadJson("/church/lista/registro/search_members", {
                list_id: listId,
                query,
            });
            if (!payload.ok) {
                showClientMessage("error", payload.message || "No se pudieron cargar los miembros.");
                return;
            }
            renderMemberResults(payload.members || []);
        } catch (err) {
            showClientMessage("error", "No se pudieron cargar los miembros en este momento.");
        }
    }

    function renderImagePreview(file) {
        if (!imagePreview) {
            return;
        }
        if (!file) {
            imagePreview.src = "";
            imagePreview.classList.add("d-none");
            return;
        }
        const reader = new FileReader();
        reader.onload = function (event) {
            imagePreview.src = event.target && event.target.result ? event.target.result : "";
            imagePreview.classList.toggle("d-none", !imagePreview.src);
        };
        reader.readAsDataURL(file);
    }

    if (toggleAccessPasswordBtn && accessPasswordInput) {
        toggleAccessPasswordBtn.addEventListener("click", function () {
            const visible = accessPasswordInput.type === "text";
            accessPasswordInput.type = visible ? "password" : "text";
            toggleAccessPasswordBtn.textContent = visible ? "Mostrar" : "Ocultar";
        });
    }

    if (validateAccessBtn) {
        validateAccessBtn.addEventListener("click", async function (event) {
            event.preventDefault();
            event.stopPropagation();
            try {
                validateAccessBtn.disabled = true;
                const payload = await postAndReadJson("/church/lista/registro/validate_access", {
                    access_password: accessPasswordInput ? accessPasswordInput.value : "",
                });
                if (!payload.ok) {
                    showClientMessage("error", payload.message || "La clave no es correcta. El formulario no será guardado.");
                    return;
                }
                if (publicSuccessMessage) {
                    publicSuccessMessage.classList.add("d-none");
                }
                showClientMessage("success", "Clave validada correctamente.");
                setStep(1);
            } catch (err) {
                showClientMessage("error", "No se pudo validar la clave en este momento.");
            } finally {
                validateAccessBtn.disabled = false;
            }
        });
    }

    if (accessPasswordInput && validateAccessBtn) {
        accessPasswordInput.addEventListener("keydown", function (event) {
            if (event.key === "Enter") {
                event.preventDefault();
                validateAccessBtn.click();
            }
        });
    }

    listSelect.addEventListener("change", function () {
        applyListConfiguration();
        showClientMessage("", "");
        setSelectedMember("", "", "0");
        hideMemberResults();
    });

    if (memberQueryInput) {
        memberQueryInput.addEventListener("input", function () {
            memberIdInput.value = "";
            if (memberSelected) {
                memberSelected.textContent = "";
            }
            clearTimeout(searchTimer);
            searchTimer = window.setTimeout(searchMembers, 250);
        });
    }

    document.addEventListener("click", function (event) {
        if (
            memberResults.contains(event.target) ||
            event.target === memberQueryInput
        ) {
            return;
        }
        hideMemberResults();
    });

    if (imageInput) {
        imageInput.addEventListener("change", function () {
            const file = imageInput.files && imageInput.files.length ? imageInput.files[0] : null;
            renderImagePreview(file);
        });
    }

    nextBtn.addEventListener("click", function () {
        if (currentStep === 1) {
            if (!listSelect.value) {
                showClientMessage("error", "Selecciona una lista.");
                return;
            }
            if (!memberIdInput.value) {
                showClientMessage("error", "Selecciona un miembro.");
                return;
            }
        }
        showClientMessage("", "");
        if (currentStep < totalSteps() - 1) {
            setStep(currentStep + 1);
        }
    });

    prevBtn.addEventListener("click", function () {
        if (currentStep > 0) {
            showClientMessage("", "");
            setStep(currentStep - 1);
        }
    });

    applyListConfiguration();
    renderImagePreview(null);
    if (memberIdInput.value && memberQueryInput.value) {
        setSelectedMember(memberIdInput.value, memberQueryInput.value, "0");
    }
    if (accessValidated === "true") {
        setStep(1);
    } else {
        setStep(0);
    }
})();
